def matrixfy(name):
    if len(name) == 0:
        return "name must be at least one letter"

    length = len(name)
    side = 1
    while side * side < length:
        side += 1

    matrix = []
    index = 0
    for _ in range(side):
        row = []
        for _ in range(side):
            if index < length:
                row.append(name[index])
                index += 1
            else:
                row.append('.')
        matrix.append(row)

    return matrix
